// RFC 9651 sf-string
export const sfString = /^(?:\u{22}(?:[\u{20}\u{21}\u{23}-\u{5B}\u{5D}-\u{7E}]|\u{5C}[\u{22}\u{5C}])*\u{22})$/u;

// RFC 9651 sf-token
