// RFC 5646 3ALPHA, a subtag of an extlang
export const extlangSubtag = /^(?:[A-Za-z]{3})$/u;

// RFC 5646 script
export const script = /^(?:[A-Za-z]{4})$/u;

// RFC 5646 region
export const region = /^(?:[A-Za-z]{2}|[0-9]{3})$/u;

// RFC 5646 variant
export const variant = /^(?:[0-9A-Za-z]{5,8}|[0-9][0-9A-Za-z]{3})$/u;

// RFC 5646 singleton
export const singleton = /^(?:[0-9A-WYZa-wyz])$/u;

// RFC 5646 2*8alphanum, a subtag of an extension after its singleton
export const extensionSubtag = /^(?:[0-9A-Za-z]{2,8})$/u;

// RFC 5646 1*8alphanum, a subtag of a privateuse after its "x"
export const privateUseSubtag = /^(?:[0-9A-Za-z]{1,8})$/u;

// RFC 5646 *alphanum
export const alphanums = /[0-9A-Za-z]*/uy;
